#!/bin/sh
# Installs the Atlantiraptor agent on macOS and connects it to your
# Atlantiraptor server.
#
# Generated by the Atlantiraptor console (Clients > Deploy a client) on
# {{.Generated}} for org "{{.OrgName}}". Server: {{.ServerURLs}}
#
# This script contains the server's client configuration: the server
# address, the CA certificate the agent trusts and the org's enrollment
# nonce. Anyone with this file can enroll a computer to your server, so
# share it only with the people who deploy agents.
#
# Installs /usr/local/atlantiraptor/atlantiraptor and the launchd daemon
# com.atlantsecurity.atlantiraptor (runs as root). The program is the file
# given with --binary, ./atlantiraptor in the current folder, or else
# downloaded from {{.ReleaseBase}}/Atlantiraptor-darwin-<arch>
# and checked against that release's SHA256SUMS.
#
# For full visibility, grant the program Full Disk Access with an MDM
# profile (PPPC payload) for /usr/local/atlantiraptor/atlantiraptor.
#
# Usage (as root):
#   sh install-atlantiraptor-macos.sh [--binary PATH] [--reinstall]
#   sh install-atlantiraptor-macos.sh --uninstall
set -eu

CONFIG_B64='{{.ConfigB64}}'
RELEASE_BASE='{{.ReleaseBase}}'
DIR=/usr/local/atlantiraptor
LABEL=com.atlantsecurity.atlantiraptor
PLIST=/Library/LaunchDaemons/$LABEL.plist

BINARY=""
ACTION=install
REINSTALL=0
while [ $# -gt 0 ]; do
  case "$1" in
    --binary) BINARY="$2"; shift 2 ;;
    --reinstall) REINSTALL=1; shift ;;
    --uninstall) ACTION=uninstall; shift ;;
    *) echo "Unknown option: $1" >&2; exit 2 ;;
  esac
done

if [ "$(id -u)" != 0 ]; then
  echo "Run this as root (sudo)." >&2; exit 1
fi

uninstall() {
  launchctl bootout system "$PLIST" >/dev/null 2>&1 || true
  rm -f "$PLIST"
  rm -rf "$DIR"
}

if [ "$ACTION" = uninstall ]; then
  uninstall
  echo "Atlantiraptor is uninstalled."
  exit 0
fi

if [ -f "$PLIST" ] && [ "$REINSTALL" = 0 ]; then
  launchctl kickstart "system/$LABEL" >/dev/null 2>&1 || true
  echo "Atlantiraptor is already installed. Use --reinstall to replace it."
  exit 0
fi

WORK=$(mktemp -d)
trap 'rm -rf "$WORK"' EXIT

if [ -z "$BINARY" ] && [ -f ./atlantiraptor ]; then
  BINARY=./atlantiraptor
fi
if [ -z "$BINARY" ]; then
  case "$(uname -m)" in
    x86_64) ARCH=amd64 ;;
    arm64) ARCH=arm64 ;;
    *) echo "No download for $(uname -m); pass --binary." >&2; exit 1 ;;
  esac
  NAME="Atlantiraptor-darwin-$ARCH"
  echo "Downloading $RELEASE_BASE/$NAME"
  if ! curl -fsSL -o "$WORK/atlantiraptor" "$RELEASE_BASE/$NAME" || ! curl -fsSL -o "$WORK/SHA256SUMS" "$RELEASE_BASE/SHA256SUMS"; then
    echo "This release has no macOS program to download. Get the atlantiraptor program for macOS" >&2
    echo "from Atlant Security (or build it with 'make darwin') and run this script again with" >&2
    echo "--binary /path/to/atlantiraptor, or put it in the current folder." >&2
    exit 1
  fi
  WANT=$(awk -v n="$NAME" '$2 == n || $2 == "*" n { print $1 }' "$WORK/SHA256SUMS")
  GOT=$(shasum -a 256 "$WORK/atlantiraptor" | awk '{ print $1 }')
  if [ -z "$WANT" ] || [ "$WANT" != "$GOT" ]; then
    echo "The download does not match the release's SHA256SUMS; not installing." >&2; exit 1
  fi
  BINARY="$WORK/atlantiraptor"
fi

if [ -f "$PLIST" ]; then uninstall; fi

mkdir -p "$DIR"
chmod 0700 "$DIR"
cp "$BINARY" "$DIR/atlantiraptor"
chmod 0700 "$DIR/atlantiraptor"
xattr -d com.apple.quarantine "$DIR/atlantiraptor" >/dev/null 2>&1 || true
echo "$CONFIG_B64" | base64 -D > "$DIR/client.config.yaml"
chmod 0600 "$DIR/client.config.yaml"

cat > "$PLIST" <<PLIST
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
  <key>Label</key>
  <string>$LABEL</string>
  <key>ProgramArguments</key>
  <array>
    <string>$DIR/atlantiraptor</string>
    <string>--config</string>
    <string>$DIR/client.config.yaml</string>
    <string>client</string>
    <string>--quiet</string>
  </array>
  <key>RunAtLoad</key>
  <true/>
  <key>KeepAlive</key>
  <true/>
</dict>
</plist>
PLIST
chmod 0644 "$PLIST"
launchctl bootstrap system "$PLIST"
echo "Atlantiraptor is installed and running. The computer appears in the console under Clients within a minute."
